{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Despite its significance, OH remains largely unintegrated into national governance and service delivery structures, with limited coordination across human health, animal health and environmental sectors [ 14 ], and only a few countries demonstrating uneven progress toward cross-sectoral integration [ 16 ].",
      "reason": "The manuscript describes the current state of knowledge—that OH is largely unintegrated, with limited coordination and uneven country progress—identifying systemic gaps and uncertainties in implementation."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "A comparative synthesis is therefore necessary to identify recurring structural barriers and enabling factors across diverse contexts. Accordingly, this systematic review synthesizes global evidence on the challenges and opportunities of integrating OH into national health systems across human, animal and environmental sectors and identifies actionable system-level strategies to support sustainable integration.",
      "reason": "The manuscript explains the importance and need for the review, arguing that a comparative synthesis is required to identify recurring barriers and enabling factors and to inform actionable strategies."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "More recent reviews published in 2025 [ 30-32 ] have examined operational challenges in rural African contexts, ethical considerations within a globalized OH framework and critical reflections from the Global South. Although these contributions broaden thematic and regional understanding, they primarily focus on conceptual or context-specific dimensions rather than systematically analysing how implementation barriers and facilitators intersect with core health system functions.",
      "reason": "The manuscript cites recent similar reviews and explains how they differ (context-specific or conceptual) and thus justifies the need for the current review as a broader comparative synthesis."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review addresses integration of One Health into health systems rather than evaluating intervention effects; no mechanism of action for an intervention is relevant or described in the supplied evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is not of a complex intervention or delivery context requiring a logic model; no logic model or hypothesised intervention–outcome relationships are relevant in the supplied evidence."
    }
  ],
  "confidence": "90"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "This review synthesizes global evidence on challenges, opportunities and strategic directions for embedding OH within health system structures.",
      "reason": "The abstract explicitly states the review objective as synthesizing global evidence on challenges, opportunities and strategic directions for embedding One Health within health system structures, fulfilling the requirement for an explicit statement of objectives/questions."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_7",
      "quote": "Eligibility criteria were structured using the PICo framework (population, interest and context), which is appropriate for non-clinical and policy-focused research questions: Population (P) : national health systems, institutions and stakeholders involved in OH implementation. Interest (I) : challenges, opportunities, barriers, facilitators and implementation strategies related to OH integration.",
      "reason": "The review addresses non-clinical, policy-focused questions about challenges and opportunities for One Health integration and uses the PICo framework; it is not a review of intervention effects requiring PICO-style planned comparisons."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Eligibility criteria were structured using the PICo framework (population, interest and context), which is appropriate for non-clinical and policy-focused research questions: Population (P) : national health systems, institutions and stakeholders involved in OH implementation. Interest (I) : challenges, opportunities, barriers, facilitators and implementation strategies related to OH integration. Context (Co) : human, animal and environmental health sectors at national or sub-national levels. This review includes peer-reviewed studies published between 1 June 2013, and 1 April 2025, examining the challenges and opportunities of OH implementation in health systems, programmes, services or strategies; the start date was selected to align with the period in which OH gained formal global policy recognition and began to be operationalized through national and international frameworks. Studies providing broader insights into OH implementation challenges and opportunities were also included, even when not explicitly focused on specific health systems or programmes, because they elucidate crosscutting governance, coordination and workforce dynamics that directly shape how OH is operationalized within human, animal and environmental health systems.",
      "reason": "Provides detailed study characteristics used to determine eligibility: PICo components (population, interest, context), eligible settings and scope, and date range."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "This review includes peer-reviewed studies published between 1 June 2013, and 1 April 2025... Only peer-reviewed journal articles published in English were included. Conference abstracts lacking full-text availability were excluded due to insufficient methodological detail, empirical findings or policy-relevant analysis required to extract implementation challenges, opportunities or recommendations. Grey literature was also excluded to ensure methodological consistency and comparability across included studies.",
      "reason": "Specifies report characteristics: publication date range, language (English), publication type (peer-reviewed only) and exclusion of conference abstracts and grey literature."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement distinguishing exclusion because outcomes were not measured from exclusion because outcome results were not reported is present in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Challenges, opportunities and recommendations were identified through iterative coding of extracted data. Statements describing barriers, constraints or implementation difficulties were categorized as challenges; descriptions of enabling conditions or supportive factors were classified as opportunities; and proposed actions or policy suggestions were categorized as recommendations: The challenges and opportunities identified in each study were compiled in tables and textual descriptions. A narrative synthesis was conducted to interpret the findings, applying a thematic analysis to systematically identify, code and synthesize barriers and facilitators of OH implementation across health system domains within human, animal and environmental sectors. ... Thematic findings were organized into structured tables to facilitate comparison across settings, and frequency patterns were described narratively to highlight recurring system-level themes.",
      "reason": "Specifies the groups used in the synthesis (challenges, opportunities, recommendations), how items were classified and that thematic findings/tables were organized to facilitate comparisons across settings."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "the start date was selected to align with the period in which OH gained formal global policy recognition and began to be operationalized through national and international frameworks. ... Conference abstracts lacking full-text availability were excluded due to insufficient methodological detail, empirical findings or policy-relevant analysis required to extract implementation challenges, opportunities or recommendations. Grey literature was also excluded to ensure methodological consistency and comparability across included studies.",
      "reason": "Provides rationales for notable restrictions: justification for the start date and reasons for excluding conference abstracts and grey literature (methodological detail, comparability)."
    }
  ],
  "confidence": 85
}

